package com.codeguardian.controller; import com.codeguardian.entity.KnowledgeFile; import com.codeguardian.repository.KnowledgeFileRepository; import com.codeguardian.service.DocumentKnowledgeService; import lombok.RequiredArgsConstructor; import org.springframework.core.io.FileSystemResource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.Path; import java.util.List; @RestController @RequestMapping("/api/knowledge/files") @RequiredArgsConstructor public class DocumentKnowledgeController{private final DocumentKnowledgeService service;private final KnowledgeFileRepository files;@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public KnowledgeFile upload(@RequestParam MultipartFile file){return service.upload(file);}@GetMapping public List<KnowledgeFile> list(){return files.findAll();}@GetMapping("/{id}/download")public ResponseEntity<FileSystemResource> download(@PathVariable Long id){Path p=service.path(id);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+p.getFileName()+"\"").body(new FileSystemResource(p));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
